  exec sz (Fminmax op FMT_D rd rs1 rs2) c =
  let r := fp_minmax fmt_double (match op with F_MIN => false | F_MAX => true end) (bv_unsigned (fget c rs1)) (bv_unsigned (fget c rs2)) in
